const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const antarctica = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, -90], [-180, -90], [-180, -60]]],
    null, false
  );

  const august_start = '2024-08-26';
  const august_end = '2024-08-30';
  const september_start = '2024-09-26';
  const september_end = '2024-09-30';

  // Ozone hole threshold: 220 DU = 0.005918 mol/m²
  const ozone_threshold = 220 * 2.69e-5;

  // 2. Data Acquisition & Check
  const col_aug = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .filterDate(august_start, august_end)
    .filterBounds(antarctica)
    .select('O3_column_number_density');

  const col_sep = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .filterDate(september_start, september_end)
    .filterBounds(antarctica)
    .select('O3_column_number_density');

  const aug_size = await col_aug.size().getInfo();
  const sep_size = await col_sep.size().getInfo();

  console.log(`August images: ${aug_size}`);
  console.log(`September images: ${sep_size}`);

  if (aug_size === 0 || sep_size === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites and identify ozone hole
  const aug_mean = col_aug.mean();
  const sep_mean = col_sep.mean();

  // Create mask for ozone hole (values < 220 DU)
  const aug_hole = aug_mean.lt(ozone_threshold);
  const sep_hole = sep_mean.lt(ozone_threshold);

  // 4. Calculate pixel counts for ozone hole area
  const aug_count = await aug_hole.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: 5000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  const sep_count = await sep_hole.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: 5000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  console.log(`August ozone hole pixels: ${aug_count}`);
  console.log(`September ozone hole pixels: ${sep_count}`);

  // Check for valid calculation
  if (aug_count === null || sep_count === null || 
      isNaN(aug_count) || isNaN(sep_count)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check for no valid pixels
  if (aug_count === 0 && sep_count === 0) {
    console.log("No ozone hole pixels detected in either period.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Compare sizes and provide answer
  console.log(`September hole is larger: ${sep_count > aug_count}`);

  if (sep_count > aug_count) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
